SELECT ei.id, model_seed.slug, model_seed.brand, model_seed.model, model_seed.display_name, model_seed.normalized_name, model_seed.specs
FROM model_seed
JOIN equipment_items ei ON ei.slug = model_seed.equipment_slug
ON CONFLICT (slug) DO UPDATE SET
  equipment_id = EXCLUDED.equipment_id,
  brand = EXCLUDED.brand,
  model = EXCLUDED.model,
  display_name = EXCLUDED.display_name,
  normalized_name = EXCLUDED.normalized_name,
  specs = EXCLUDED.specs,
  is_active = true,
  updated_at = now();

CREATE TEMP TABLE manual_hongdae_naver_equipment_assignment (
  studio_slug TEXT NOT NULL, room_name TEXT NOT NULL, equipment_slug TEXT NOT NULL, model_slug TEXT,
  quantity SMALLINT NOT NULL, is_optional BOOLEAN NOT NULL, details JSONB NOT NULL
);


CREATE TEMP TABLE manual_hongdae_naver_equipment_evidence (
  studio_slug TEXT NOT NULL, room_name TEXT NOT NULL, equipment_slug TEXT NOT NULL, model_slug TEXT,
  is_optional BOOLEAN NOT NULL, details JSONB NOT NULL, evidence_key TEXT NOT NULL, source_url TEXT NOT NULL,
  source_title TEXT NOT NULL, raw_text TEXT NOT NULL, parsed_name TEXT NOT NULL, confidence TEXT NOT NULL
);


DELETE FROM room_equipment re
USING manual_hongdae_naver_equipment_assignment assignment
JOIN studios s ON s.slug = assignment.studio_slug
JOIN rooms r ON r.studio_id = s.id AND r.name = assignment.room_name
JOIN equipment_items ei ON ei.slug = assignment.equipment_slug
LEFT JOIN equipment_models em ON em.slug = assignment.model_slug
WHERE re.room_id = r.id
  AND re.equipment_id = ei.id
  AND ((assignment.model_slug IS NULL AND re.equipment_model_id IS NULL) OR re.equipment_model_id = em.id)
  AND re.position_label IS NULL;

SELECT
  r.id,
  ei.id,
  em.id,
  SUM(assignment.quantity)::smallint,
  NULL,
  'MANUAL',
  NULL,
  bool_or(assignment.is_optional),
  CASE
    WHEN COUNT(*) = 1 THEN MIN(assignment.details::text)::jsonb
    ELSE jsonb_build_object('items', jsonb_agg(assignment.details ORDER BY assignment.details::text))
  END
FROM manual_hongdae_naver_equipment_assignment assignment
JOIN studios s ON s.slug = assignment.studio_slug
JOIN rooms r ON r.studio_id = s.id AND r.name = assignment.room_name
JOIN equipment_items ei ON ei.slug = assignment.equipment_slug
LEFT JOIN equipment_models em ON em.slug = assignment.model_slug
GROUP BY r.id, ei.id, em.id;

  evidence_key, target_kind, studio_id, room_id, equipment_id, equipment_model_id, room_equipment_id, source_kind,
  source_url, source_title, raw_name, raw_text, parsed_name, position_label, is_optional, confidence, observed_at
)
SELECT evidence.evidence_key, 'ROOM', NULL, r.id, ei.id, em.id, re.id, 'NAVER_BOOKING',
  evidence.source_url, evidence.source_title, '방 설명', evidence.raw_text, evidence.parsed_name, NULL, evidence.is_optional, evidence.confidence, '2026-07-22T12:10:00+09:00'::timestamptz
FROM manual_hongdae_naver_equipment_evidence evidence
JOIN studios s ON s.slug = evidence.studio_slug
JOIN rooms r ON r.studio_id = s.id AND r.name = evidence.room_name
JOIN equipment_items ei ON ei.slug = evidence.equipment_slug
LEFT JOIN equipment_models em ON em.slug = evidence.model_slug
JOIN room_equipment re ON re.room_id = r.id
  AND re.equipment_id = ei.id
  AND ((evidence.model_slug IS NULL AND re.equipment_model_id IS NULL) OR re.equipment_model_id = em.id)
  AND re.position_label IS NULL
ON CONFLICT (evidence_key) DO UPDATE SET
  room_id = EXCLUDED.room_id, equipment_id = EXCLUDED.equipment_id, equipment_model_id = EXCLUDED.equipment_model_id,
  room_equipment_id = EXCLUDED.room_equipment_id, source_kind = EXCLUDED.source_kind, source_url = EXCLUDED.source_url,
  source_title = EXCLUDED.source_title, raw_name = EXCLUDED.raw_name, raw_text = EXCLUDED.raw_text, parsed_name = EXCLUDED.parsed_name,
  position_label = EXCLUDED.position_label, is_optional = EXCLUDED.is_optional, confidence = EXCLUDED.confidence, observed_at = EXCLUDED.observed_at;

DROP TABLE manual_hongdae_naver_equipment_evidence;
DROP TABLE manual_hongdae_naver_equipment_assignment;

CREATE TEMP TABLE manual_hongdae_naver_equipment_review (studio_slug TEXT NOT NULL, room_name TEXT NOT NULL, evidence_key TEXT NOT NULL, source_url TEXT NOT NULL, source_title TEXT NOT NULL, raw_text TEXT NOT NULL);


SELECT review.evidence_key, 'ROOM', NULL, r.id, NULL, NULL, NULL, 'NAVER_BOOKING', review.source_url, review.source_title, '방 설명', review.raw_text, NULL, NULL, false, 'NEEDS_REVIEW', '2026-07-22T12:10:00+09:00'::timestamptz
FROM manual_hongdae_naver_equipment_review review
JOIN studios s ON s.slug = review.studio_slug
JOIN rooms r ON r.studio_id = s.id AND r.name = review.room_name
ON CONFLICT (evidence_key) DO UPDATE SET
  room_id = EXCLUDED.room_id, equipment_id = EXCLUDED.equipment_id, equipment_model_id = EXCLUDED.equipment_model_id, room_equipment_id = EXCLUDED.room_equipment_id, source_kind = EXCLUDED.source_kind, source_url = EXCLUDED.source_url, source_title = EXCLUDED.source_title, raw_name = EXCLUDED.raw_name, raw_text = EXCLUDED.raw_text, parsed_name = EXCLUDED.parsed_name, position_label = EXCLUDED.position_label, is_optional = EXCLUDED.is_optional, confidence = EXCLUDED.confidence, observed_at = EXCLUDED.observed_at;

DROP TABLE manual_hongdae_naver_equipment_review;
